    /* 사용자 조회 */
    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var values = {
            noPaging : 'dummyForNoPaging',
            /*필요 데이터만 뽑아서 넘겨주기.*/
            xpnitKeyCd : vm.get('expItemInputData.xpnitKeyCd'),
            /* 사업관리 공통 쿼리를 사용하기위해 파라미터 변수명 맞추기 . */
            criDate : vm.get('expItemInputData.bsnsDt'),
            criYy : vm.get('expItemInputData.bsnsYy'),
            bgBudcBsnsId : vm.get('expItemInputData.bgBudcBsnsId'),
            actgQut : DateUtils.getQuarter(new Date(DateUtils.parseDate(vm.get('expItemInputData.bsnsDt'))))
        };

        var selectedRecord = {};
        if(vm.get('StandardCombobox') == Constants.nfcmAplyTrgtSttCbx.XPNIT){
            selectedRecord = refs.bgBudcBsnsId.getSelection();
        }else {
            selectedRecord = refs.xpnitKeyCd.getSelection();
        }

        if(selectedRecord){
            values.bgBudcXpnitYyId = selectedRecord.data.bgBudcXpnitYyId;
        }


        /*  SEARCH FORM 내에 있는 값이 제대로 입력이되어있는지 확인 후 처리 */
        if( !vm.get('expItemInputData.xpnitKeyCd') ||  !vm.get('expItemInputData.bgBudcBsnsId')){
            var msg = '사업부문과 계정과목을 선택해주세요.';
            if (msg) {
                me.showAlert(msg);
                return false;
            }
        }

        //현재 활성화된 탭의 onSelect 함수를 호출함.
        Ext.Ajax.request({
            headers : {
                serviceId : 'BgxNfmSvc.findAllBgmExpIfUser',
                viewId : me.getViewId()
            },
            jsonData : values,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                me.setBuddLmtAmt(res.lmtInfo).then(function() {
                    // 페이지정보 설정
                    refs.userGrid.setData(res.page.content);
                });
            }
        });
    },

    /* 사용자 중복체크 */
    checkUser: function(data) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            userList = vm.get('userList');

        for (var user in userList) {
            var tmp = userList[user];
            if (tmp.bgBudcBsnsId == data.bgBudcBsnsId && tmp.bsnsNm == data.bsnsNm && tmp.bsnsYy == data.bsnsYy && tmp.dpnm == data.dpnm && tmp.enpnm == data.enpnm && tmp.stfNm == data.stfNm && tmp.stfNo == data.stfNo) {
                return true;
            }
        }

        return false;
    },

    showAlert: function(msg) {
        Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : msg,
                alwaysOnTop : true,
                fn : function(btn) {
                    return;
                }
            });
    },

